  "it.f_80c": "Old regime: 80C-type deductions",
  "it.f_80c_h": "PF, life insurance, tax-saving funds and the like; limited to ₹1,50,000. Section 123 in the Income-tax Act 2025.",
  "it.f_dedo": "Old regime: other deductions",
  "it.f_dedo_h": "Health insurance, home loan interest on a self-occupied house, NPS extra and so on, added up by you.",
  "it.f_nps": "Employer NPS contribution",
  "it.f_nps_h": "Allowed in both regimes; type the amount.",
  "it.f_sur": "Surcharge",
  "it.f_sur_h": "Not worked out. Type the amount if your income is above ₹50 lakh.",
  "it.f_tds": "TDS and TCS cut on this income",
  "it.f_tds_h": "Starts from the TDS recorded in your receipts and other income for the year. Add what is still to be cut.",
  "it.f_def": "Tax on gains or profit that will come later",
  "it.f_def_h": "Capital gains, dividend or first-year business profit you have not earned yet: not counted for the earlier instalments if paid in the remaining ones.",
  "it.f_mon": "Months of interest if tax is short",
  "it.f_mon_h": "From 1 April after the year to the day the return is processed. 4 = a return filed by 31 July.",
  "it.m_senior": "A resident aged 60 or more with no business or professional income does not pay advance tax (section 403(3)). Pay the balance when you file the return.",
  "it.m_below": "The tax after TDS is {n}, below ₹10,000, so no advance tax is due (section 404). Pay the balance when you file the return.",
  "it.m_pres": "With a presumptive scheme the whole advance tax is paid on or before 15 March (section 408(2)).",
  "it.m_sur": "Your income is above ₹50 lakh: type the surcharge, it is not worked out here.",
  "it.m_past": "This year is over. Advance tax paid after 31 March does not count as advance tax for it; interest below shows what a shortfall costs.",
