  "pr.rates_pf": "नेहमीच्या EPF नियमांनुसार सेट: पगार मर्यादा ₹25,000 महिना (17 Sep 2026 पासून), कर्मचारी 12%, पेन्शन (EPS) 8.33%, EDLI 0.5%, ॲडमिनिस्ट्रेशन 0.5% किमान ₹500. भरण्याआधी EPFO साइटवर ते तपासा.",
  "pr.rates_esi": "पगाराच्या कर्मचारी 0.75% आणि मालक 3.25%, प्रत्येकी पुढच्या रुपयापर्यंत वाढवून (Social Security (Central) Rules, 2026, rule 19). पगार मर्यादा ₹21,000 महिना: सध्याची मर्यादा ESIC साइटवर तपासा. रोजचा पगार ₹176 किंवा कमी असेल तर कर्मचाऱ्याचा हिस्सा नाही (ESIC contribution page).",
