  "pr.pfintro": "महिन्याच्या सॅलरी स्लिपमधून EPFO unified portal साठी ECR टेक्स्ट फाइल आणि चलनाच्या रकमा बनतात. आधी स्लिप बनवा (सॅलरी टॅब); स्लिप नसलेले कर्मचारी खाली दिसतात.",
  "pr.unver_pf": "अपलोड करण्याआधी तपासा: हे बनवले तेव्हा (14 Nov 2026) EPFO चे स्वतःचे फाइल-रचनेचे डॉक्युमेंट उघडता आले नाही. 11 फील्ड आणि त्यांचा क्रम पेरोल सॉफ्टवेअर बनवणारे जे प्रसिद्ध करतात त्यानुसार आहे. फाइल EPFO पोर्टलच्या ECR पेजवर अपलोड करा; पोर्टलने एखादी ओळ नाकारली तर ते कारण सांगते.",
