  "it.basis": "हे आकडे कशावर आधारित आहेत ({d} रोजी)",
  "it.b1": "दर ({d} रोजी), टॅक्स वर्ष 2026-27: नवीन रिजीम ₹4 लाखांपर्यंत शून्य, ₹8 लाखांपर्यंत 5%, ₹12 लाखांपर्यंत 10%, ₹16 लाखांपर्यंत 15%, ₹20 लाखांपर्यंत 20%, ₹24 लाखांपर्यंत 25%, त्यापेक्षा जास्त 30%; ₹12 लाखांपर्यंतच्या उत्पन्नावर टॅक्स लागू नये असा रिबेट, त्याच्या थोडे वर मार्जिनल रिलीफसह; पगारावर स्टँडर्ड डिडक्शन ₹75,000. जुनी रिजीम: ₹2.5 लाखांपर्यंत शून्य (60 वयाला ₹3 लाख, 80 ला ₹5 लाख), ₹5 लाखांपर्यंत 5%, ₹10 लाखांपर्यंत 20%, त्यापेक्षा जास्त 30%; ₹5 लाखांपर्यंत रिबेट ₹12,500; स्टँडर्ड डिडक्शन ₹50,000. सॅलरी स्लिप टूल आधीच हेच दर वापरते; या बिल्डमध्ये ते Finance Act मधून पुन्हा वाचले नाहीत, म्हणून ते तपासा.",
  "it.b2": "ॲडव्हान्स टॅक्स (Income-tax Act 2025, sections 403 ते 408): TDS नंतरचा टॅक्स ₹10,000 किंवा जास्त असेल तेव्हा देय; 15 जूनपर्यंत 15%, 15 सप्टेंबरपर्यंत 45%, 15 डिसेंबरपर्यंत 75%, 15 मार्चपर्यंत सगळा; प्रिझम्प्टिव्ह करदाता सगळा 15 मार्चपर्यंत भरतो; 31 मार्चपर्यंतचे पेमेंट त्या वर्षासाठी धरले जाते; बिझनेस उत्पन्न नसलेल्या 60 किंवा जास्त वयाच्या रहिवाशाला सूट आहे.",
  "it.b3": "व्याज: section 424 (जुने 234B) म्हणजे टॅक्सच्या 90% पेक्षा कमी भरले असल्यास कमतरतेवर दरमहा किंवा महिन्याच्या भागाला 1%; section 425 (जुने 234C) म्हणजे पहिल्या तीन हप्त्यांपैकी प्रत्येकाच्या कमतरतेवर 3% (15 जूनपर्यंत 12% आणि 15 सप्टेंबरपर्यंत 36% भरले असल्यास काही नाही) आणि मार्चच्या कमतरतेवर 1%.",
  "it.b5": "हिशोबातील नफा म्हणजे टॅक्सेबल नफा नाही: Act खालील घसारा, नाकारलेले खर्च आणि प्रिझम्प्टिव्ह नियम तो बदलतात. हा प्लॅन आणि डेटा शीट तुमच्या अकाउंटंटला द्या.",
  "it.b6": "काढलेले नाही: सरचार्ज, विशेष दराने कॅपिटल गेन, परदेशी टॅक्स रिलीफ, अल्पवयीनाच्या उत्पन्नावरील टॅक्स आणि उशिरा फाइल करण्याचे व्याज.",
  "it.b7": "काहीही फाइल होत नाही आणि तुमच्या हिशोबात काहीही नोंदवले जात नाही.",
  "it.itr_h": "कोणता रिटर्न फॉर्म बसतो, का, आणि कोणती कागदपत्रे तयार ठेवायची हे पाहण्यासाठी काही प्रश्नांची उत्तरे द्या.",
