  "it.formd_ITR-1": "पगार किंवा पेन्शन, दोन घरांच्या प्रॉपर्टीपर्यंत आणि व्याजासारखे इतर स्रोत असलेल्या आणि एकूण उत्पन्न ₹50 लाखांपर्यंत असलेल्या रहिवासी व्यक्तीसाठी.",
  "it.formd_ITR-2": "बिझनेस किंवा प्रोफेशनचे उत्पन्न नसलेल्या पण कॅपिटल गेन, ₹50 लाखांपेक्षा जास्त उत्पन्न, दोनपेक्षा जास्त घरांच्या प्रॉपर्टी, परदेशी मालमत्ता किंवा उत्पन्न असलेल्या, किंवा ITR-1 मध्ये न बसणाऱ्या व्यक्ती किंवा HUF साठी.",
