  "it.formd_ITR-5": "फर्म, LLP, असोसिएशन ऑफ पर्सन्स आणि बॉडी ऑफ इंडिव्हिज्युअल्ससाठी.",
  "it.formd_ITR-6": "धर्मादाय किंवा धार्मिक कारणासाठी सूट मागणाऱ्या कंपन्या सोडून इतर कंपन्यांसाठी.",
