  "it.w_simple": "मर्यादेत फक्त पगार, घराची प्रॉपर्टी आणि व्याज असल्यास ITR-1 मध्ये बसते.",
  "it.n_forms": "अटी 31 मार्च 2026 ला संपलेल्या वर्षासाठी नोटिफाय केलेल्या रिटर्ननुसार आहेत (टॅक्स पोर्टलनुसार, ITR-1 आणि ITR-4 मध्ये आता दोन घरांच्या प्रॉपर्टीपर्यंत चालते). टॅक्स वर्ष 2026-27 चे रिटर्न Income-tax Rules, 2026 खाली अजून नोटिफाय व्हायचे आहेत: फाइल करण्याआधी फॉर्ममधील कोण वापरू शकत नाही याची स्वतःची यादी वाचा.",
  "it.n_ltcg": "लिस्टेड शेअर किंवा इक्विटी फंडवरील लहान लाँग-टर्म गेन काही वर्षी ITR-1 आणि ITR-4 मध्ये चालत होते; 2026-27 साठी याची खात्री झालेली नाही, म्हणून ITR-2 सुरक्षित निवड आहे आणि फॉर्मची स्वतःची यादी अंतिम आहे.",
  "it.n_ae": "Section 44AE (मालवाहू गाड्या) च्या स्वतःच्या अटी आहेत; प्रिझम्प्टिव्ह फॉर्म वापरण्याआधी त्या तपासा.",
