  "nav.ca": "अकाउंटंट व्ह्यूअर",
  "ca.mk": "माझ्या अकाउंटंटसाठी फाइल बनवा (फक्त वाचण्यासाठी)",
  "ca.t": "माझ्या अकाउंटंटसाठी फाइल",
  "ca.intro": "एक बिझनेस आणि कालावधी एकाच फक्त-वाचण्याच्या फाइलमध्ये (.nsca) बांधते. ती तुमच्या अकाउंटंटला WhatsApp किंवा ईमेलने पाठवा. ते ती ca.niveshsahayak.in वर उघडतात, हिशोब वाचतात, प्रश्न जोडतात आणि कमेंट तुम्हाला परत पाठवतात.",
  "ca.notlive": "हे फाइल देणे आहे, लाइव्ह शेअर केलेले लॉगिन नाही. तुम्ही फाइल बनवली तेव्हा हिशोब जसा होता तसा तुमचा अकाउंटंट पाहतो. लाइव्ह लॉगिनसाठी तुमचा हिशोब साठवणारा सर्व्हर लागेल, आणि Nivesh Sahayak कडे असा सर्व्हर नाही: तुमचा हिशोब तुमच्या डिव्हाइसवरच राहतो. नवीन एंट्रीसाठी नवीन फाइल बनवा.",
  "ca.what": "काय जाते",
  "ca.earlier": "पहिल्या तारखेआधीच्या एंट्रीसुद्धा (सुरुवातीच्या बाकी आणि एजिंगसाठी आवश्यक)",
  "ca.items": "खरेदी आणि विक्री दरांसह आयटम लिस्ट (स्टॉकसाठी आवश्यक)",
  "ca.extra": "फक्त तुम्ही टिक केले तर",
  "ca.extrah": "तुम्ही टिक करेपर्यंत सोडले जाते. चित्रे (लोगो, सही), तुमचा PIN आणि बॅकअप सेटिंग कधीच समाविष्ट होत नाहीत.",
  "ca.orders": "कोटेशन, प्रोफॉर्मा इनव्हॉइस, सेल्स ऑर्डर, चलन आणि पर्चेस ऑर्डर",
  "ca.staff": "सॅलरी स्लिप, स्टाफ ॲडव्हान्स, लोन आणि EMI, पेटी कॅश आणि कर्मचारी लिस्ट",
  "ca.phones": "पार्टीचे फोन नंबर, ई-मेल पत्ते आणि WhatsApp नंबर",
