  "ca.code": "चेक कोड:",
  "ca.codeh": "हा कोड तुमच्या मेसेजमध्ये पाठवा, किंवा कॉलवर वाचून सांगा. तुमचा अकाउंटंट फाइलवर दिसणाऱ्या कोडशी त्याची तुलना करतो, त्यामुळे वाटेत बदललेली फाइल लक्षात येते.",
