  "ca.how": "फाइल WhatsApp किंवा ई-मेलने अटॅचमेंट म्हणून पाठवा. WhatsApp नावाच्या शेवटी .nsca दाखवत असेल तर नाव बदलू नका.",
  "ca.cT": "CA कमेंट",
  "ca.cIntro": "तुमचा अकाउंटंट प्रश्न आणि कमेंटची एक छोटी फाइल (.nsca-comments) परत पाठवतो. प्रत्येक प्रश्न ज्या एंट्रीबद्दल आहे तिच्या शेजारी पाहण्यासाठी ती इथे लोड करा. उत्तर द्या, बंद मार्क करा आणि परत पाठवण्यासाठी फाइल पुन्हा सेव्ह करा.",
