  "ca.party": "पार्टी",
  "ca.screen": "स्क्रीन",
  "ca.general": "सामान्य कमेंट",
  "cv.h1": "अकाउंटंट व्ह्यूअर: तुमच्या क्लायंटने पाठवलेली हिशोबाची फाइल उघडा",
  "cv.intro": "तुमचा क्लायंट एका कालावधीचा हिशोब एका फाइलमध्ये बांधतो आणि तुम्हाला WhatsApp किंवा ईमेलने पाठवतो. ती इथे उघडा आणि वाचा: येणे-देणे, पार्टी, लेजर, डे बुक, GST हिशोब, फायनल अकाउंट आणि प्रत्येक डॉक्युमेंट. शोधा आणि फिल्टर करा, कोणत्याही एंट्रीवर प्रश्न विचारा आणि तुमच्या कमेंट एका छोट्या फाइलमध्ये परत पाठवा. मोफत, लॉगिन नाही, आणि काहीही अपलोड होत नाही: फाइल तुमच्या ब्राउझरमध्येच वाचली जाते.",
  "cv.drop": ".nsca फाइल इथे सोडा",
  "cv.choose": "फाइल निवडा",
  "cv.dropnote": "फाइल या डिव्हाइसवरच राहते. इथे काहीही सेव्ह होत नाही आणि इथून तुम्ही तुमच्या क्लायंटचा हिशोब बदलू शकत नाही.",
  "cv.nav.home": "आढावा",
  "cv.docs": "डॉक्युमेंट",
  "cv.day": "डे बुक",
  "cv.fin": "फायनल अकाउंट",
  "cv.gst": "GST हिशोब",
  "cv.cT": "प्रश्न आणि कमेंट",
  "cv.how.h": "हे कसे चालते",
  "cv.how.1": "तुमचा क्लायंट Nivesh Sahayak उघडतो, माझा डेटा, तुमच्या अकाउंटंटला पाठवा मध्ये जातो आणि एका बिझनेस आणि कालावधीसाठी “माझ्या अकाउंटंटसाठी फाइल बनवा” निवडतो.",
  "cv.how.2": "ते तुम्हाला फाइल (.nsca ने संपणारी) आणि त्याच मेसेजमध्ये एक छोटा चेक कोड पाठवतात.",
  "cv.how.3": "तुम्ही ही फाइल या पेजवर उघडता. फाइल बदललेली नाही का ते पेज सांगते आणि तुमच्या क्लायंटने दिलेला चेक कोड तुलना करण्यासाठी लिहू देते.",
  "cv.how.4": "हिशोब वाचा, शोधा आणि कोणत्याही डॉक्युमेंट, डे-बुक एंट्री किंवा स्क्रीनवर “प्रश्न किंवा कमेंट जोडा” दाबा. तुम्ही लिहिलेले सगळे या ब्राउझरमध्येच राहते.",
  "cv.how.5": "झाल्यावर “प्रश्न आणि कमेंट” उघडा आणि छोटी .nsca-comments फाइल परत पाठवा. तुमचा क्लायंट ती लोड करतो आणि प्रत्येक प्रश्न एंट्रीच्या शेजारी पाहतो. ते उत्तर देऊ शकतात, आणि तुम्ही उत्तरे इथे लोड करू शकता.",
  "cv.live.h": "फाइल देणे, लाइव्ह लॉगिन नाही",
  "cv.live.p": "हे फाइल देणे आहे. तुम्ही तुमच्या क्लायंटच्या अकाउंटमध्ये लॉगिन करत नाही आणि ते नंतर करत असलेले बदल तुम्हाला दिसत नाहीत. लाइव्ह शेअर केलेल्या लॉगिनसाठी हिशोब साठवणारा सर्व्हर लागेल, आणि Nivesh Sahayak कडे असा सर्व्हर नाही: हिशोब तुमच्या क्लायंटच्या डिव्हाइसवरच राहतो. नवीन कालावधीसाठी किंवा दुरुस्तीनंतर तुमच्या क्लायंटकडे नवीन फाइल मागा.",
  "cv.safe.h": "फाइलमध्ये काय आहे आणि काय नाही",
  "cv.safe.p": "काय जाते ते तुमचा क्लायंट टिक करतो. डिफॉल्टनुसार फाइलमध्ये कालावधीच्या शेवटपर्यंतच्या एका बिझनेसच्या एंट्री, पार्टी आणि आयटम असतात. कोटेशन आणि ऑर्डर, पगार आणि स्टाफचे रेकॉर्ड, फोन नंबर आणि ई-मेल पत्ते आणि बिझनेसच्या बँक खात्याचे तपशील तुमचा क्लायंट टिक करेपर्यंत सोडले जातात. चित्रे, PIN आणि बॅकअप सेटिंग कधीच समाविष्ट होत नाहीत. फाइलमध्ये चेकसम असतो, त्यामुळे तिच्यातील कोणताही बदल या पेजवर दिसतो. फाइल एडिट करून चेकसम पुन्हा काढणाऱ्याला चेकसम थांबवू शकत नाही, म्हणून तुमच्या क्लायंटने वेगळा पाठवलेल्या चेक कोडशी तुलना करा.",
  "cv.readonly": "हे फाइलचे फक्त-वाचण्याचे दृश्य आहे: इथे काहीही बदलता किंवा सेव्ह करता येत नाही.",
  "cv.notfile": "ही Nivesh Sahayak अकाउंटंट फाइल (.nsca) नाही.",
  "cv.iscomments": "ही कमेंट फाइल आहे. आधी हिशोबाची फाइल (.nsca) उघडा, मग “प्रश्न आणि कमेंट” मधून कमेंट लोड करा.",
  "cv.newer": "ही फाइल नवीन व्हर्जनने बनवली आहे. हे पेज रीलोड करा आणि पुन्हा प्रयत्न करा.",
