  "hm.me.note": "टिक तुमच्या आहेत: App प्रत्येक टप्प्याशेजारी फक्त तुमच्या रेकॉर्डमधील माहिती दाखवते. त्या प्रत्येक बिझनेस आणि महिन्यासाठी तुमच्या डेटासोबत सेव्ह होतात, म्हणजे तुमच्या बॅकअपसोबत जातात.",
  "hm.h.need": "हेल्थ स्कोअरसाठी आजच्या आधीच्या किमान 3 पूर्ण महिन्यांची बिले आणि खर्च लागतात. आतापर्यंत {n} महिने सापडले.",
