  "hm.h.chip": "तब्येत {n}/100",
  "hm.h.note": "हा तुम्ही नोंदवलेल्या बिले आणि खर्चावरून ढोबळ अंदाज आहे, अकाउंटिंग किंवा आर्थिक सल्ला नाही. हातातील स्टॉक आणि न नोंदवलेली बिले धरलेली नाहीत; मार्जिन म्हणजे त्याच महिन्यांच्या विक्रीतून खरेदी आणि खर्च वजा.",
  "hm.h.cash": "रोख पुरवठा",
  "hm.h.cash.how": "रोख आणि बँक {c}. तुम्ही खरेदी आणि खर्चावर महिन्याला सुमारे {b} खर्च करता, म्हणून हे पैसे {m} महिने पुरतात.",
  "hm.h.cash.good": "चांगली गादी. ती टिकवा, आणि पुढच्या महिन्यातील मोठी पेमेंट लक्षात ठेवा.",
  "hm.h.cash.ok": "पातळ गादी. थकलेले पैसे वसूल करा आणि सध्या मोठी खरेदी टाळा.",
