  "hm.h.cash.rule": "रोख आणि बँक बॅलन्स भागिले मागच्या 3 पूर्ण महिन्यांची सरासरी मासिक खरेदी आणि खर्च. 2 महिने किंवा जास्त म्हणजे 100, काहीही नाही किंवा कमी म्हणजे 0.",
  "hm.h.recv": "येण्याचे दिवस",
  "hm.h.recv.how": "ग्राहकांकडे {r} येणे आहे. तुम्ही दिवसाला सुमारे {d} विकता, म्हणून बिलाचे पैसे परत यायला सुमारे {n} दिवस लागतात.",
  "hm.h.recv.good": "पैसे लवकर परत येतात. उशीर करणाऱ्यांना आठवण करत राहा.",
  "hm.h.recv.ok": "पैसे हळू परत येतात. बाकी स्क्रीनवरून दर आठवड्याला आठवण पाठवा.",
  "hm.h.recv.low": "पैसे ग्राहकांकडे खूप काळ अडकले आहेत. आधी सर्वात जुन्या बिलांचा पाठपुरावा करा आणि नवीन ऑर्डरआधी अर्धे पेमेंट मागा.",
  "hm.h.recv.rule": "ग्राहकांकडे अजून येणे असलेले पैसे भागिले मागच्या 3 पूर्ण महिन्यांतील दिवसाची विक्री. 30 दिवस किंवा कमी म्हणजे 100, 90 दिवस किंवा जास्त म्हणजे 0.",
  "hm.h.margin": "मार्जिन",
  "hm.h.margin.how": "मागच्या 3 महिन्यांत तुम्ही विकलेल्या प्रत्येक 100 पैकी खरेदी आणि खर्चानंतर {p} उरले. त्याआधीचे 3 महिने: {q}.",
  "hm.h.margin.how1": "मागच्या 3 महिन्यांत तुम्ही विकलेल्या प्रत्येक 100 पैकी खरेदी आणि खर्चानंतर {p} उरले.",
  "hm.h.margin.good": "चांगला हिस्सा उरतो. किंमत बदलताना तो जपा.",
  "hm.h.margin.ok": "मार्जिन पातळ आहे किंवा कमी होत आहे. तुमच्या विक्रीच्या किमती आणि मुख्य आयटमची किंमत तपासा.",
  "hm.h.margin.low": "जवळजवळ काहीच उरत नाही. किमती वाढवा, खर्च कमी करा किंवा तोट्यातील आयटम विकणे बंद करा.",
  "hm.h.margin.rule": "मागच्या 3 पूर्ण महिन्यांची विक्रीतून खरेदी आणि खर्च वजा, विक्रीचा हिस्सा म्हणून. 15 किंवा जास्त म्हणजे 100, 0 किंवा कमी म्हणजे 0; आधीच्या 3 महिन्यांच्या तुलनेत 5 पॉइंटपेक्षा जास्त कमी झाल्यास 20 पॉइंट वजा. हातातील स्टॉक धरलेला नाही.",
  "hm.h.creep": "खर्चाची वाढ",
  "hm.h.creep.how": "मागच्या महिन्यात तुमचा खर्च {l} होता; त्याआधीच्या 3 महिन्यांची सरासरी {a} होती. हा {p}% बदल आहे.",
  "hm.h.creep.good": "खर्च स्थिर आहेत.",
  "hm.h.creep.ok": "खर्च वाढत आहेत. रिपोर्ट स्क्रीनवर कोणता हेड वाढला ते पहा.",
  "hm.h.creep.low": "खर्च अचानक वाढले. वाढलेला हेड शोधा, आणि ते एकदाचे बिल नाही ना ते तपासा.",
  "hm.h.creep.rule": "मागच्या पूर्ण महिन्याचा खर्च त्याआधीच्या 3 महिन्यांच्या सरासरीशी. 5% किंवा कमी वाढ म्हणजे 100, 40% किंवा जास्त वाढ म्हणजे 0. एकदाचे मोठे बिल एका महिन्यासाठी हे कमी करेल.",
  "hm.rm.t": "या डिव्हाइसवरील आठवणी",
  "hm.rm.p": "तुम्ही App उघडल्यावर आज कशाकडे लक्ष द्यायचे ते दाखवते. सर्वात तातडीच्या ओळींसाठी, प्रत्येकी दिवसातून एकदा, फोन नोटिफिकेशन दाखवू देऊ शकता.",
