  "hm.rm.nosupport": "हा ब्राउझर नोटिफिकेशनला सपोर्ट करत नाही. माझा दिवस मधील लिस्ट तरीही चालते.",
  "hm.rm.denied": "या साइटसाठी नोटिफिकेशन ब्लॉक आहेत. ब्राउझरच्या साइट सेटिंगमध्ये ते चालू करा, मग बॉक्स पुन्हा टिक करा.",
  "hm.rm.off": "नोटिफिकेशन बंद आहेत.",
  "hm.rm.set": "नोटिफिकेशन चालू आहेत. तुम्ही App उघडल्यावर सर्वात तातडीच्या ओळी दिसतील.",
  "hm.rm.title": "{b}: आज तुमची गरज आहे",
  "hm.rm.ics": "देय तारखा तुमच्या फोनच्या कॅलेंडरमध्ये टाका",
  "hm.rm.icsp": "पुढच्या 60 दिवसांची कॅलेंडर फाइल बनवते: बिलांच्या देय तारखा आणि टॅक्सच्या तारखा. त्या तुमच्या स्वतःच्या कॅलेंडरमध्ये जोडण्यासाठी फोनवर ती उघडा; हे App बंद असतानासुद्धा कॅलेंडर एक दिवस आधी आपोआप वाजते.",
