  "hm.rm.icsdone": "{n} तारखांसह कॅलेंडर फाइल बनली. त्या जोडण्यासाठी ती उघडा.",
  "hm.rm.recv": "वसूल करा",
  "hm.rm.pay": "भरा",
  "hm.rm.lim": "ब्राउझर काय करू शकत नाही",
  "hm.rm.l1": "बंद असताना वेब पेज चालू शकत नाही, आणि तुम्हाला पुश मेसेज पाठवण्यासाठी या App मागे कोणताही सर्व्हर नाही. म्हणून App कडून आठवण फक्त तुम्ही App उघडल्यावरच दिसते.",
  "hm.rm.l2": "सगळे तुमच्या डिव्हाइसवरच काढले जाते, त्यामुळे इंटरनेटशिवाय चालते. तुमच्या बिझनेसबद्दल काहीही कुठेही पाठवले जात नाही.",
  "hm.rm.l3": "चुकवू नयेत अशा तारखांसाठी कॅलेंडर फाइल वापरा: तुमच्या फोनचे कॅलेंडर आपोआप वाजते. ती आजची स्थिती आहे, म्हणून नवीन बिले नोंदवल्यानंतर नवीन फाइल बनवा.",
  "hm.rm.l4": "इन्स्टॉल केलेल्या App वर, तुमचा फोन परवानगी देत असेल तिथे, आयकॉनवरील आकडा किती तातडीच्या गोष्टी आहेत ते दाखवतो.",
